    private static nint GetcapsTrampoline(nint dec, nint filter)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(dec) is not AudioDecoder managed)
            {
                return ChainUpGetcaps(dec, filter);
            }

            using Gst.Caps? filterValue = filter == nint.Zero ? null : Gst.Caps.Borrow(filter);
            Gst.Caps? result = managed.OnGetcaps(filterValue);
            if (result is null)
            {
                throw new InvalidOperationException(
                    "OnGetcaps answered null, which getcaps does not allow.");
            }

            return result is null ? nint.Zero : result.HandOver();
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return Gst.GstNative.CapsNewEmpty();
        }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int TransformMetaTrampoline(nint enc, nint outbuf, nint meta, nint inbuf)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(enc) is not AudioDecoder managed)
            {
                return (ChainUpTransformMeta(enc, outbuf, meta, inbuf)) ? 1 : 0;
            }

            using Gst.Buffer? outbufValue = outbuf == nint.Zero ? null : Gst.Buffer.Borrow(outbuf);
            Gst.Meta? metaValue = Gst.Meta.FromNative(meta);
            using Gst.Buffer? inbufValue = inbuf == nint.Zero ? null : Gst.Buffer.Borrow(inbuf);
            return (managed.OnTransformMeta(outbufValue!, metaValue!, inbufValue!)) ? 1 : 0;
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return default;
        }
    }
}
